/**
 * Clip titles via the Phase-3 generation routing (Phase 5, slice 5.4).
 *
 * A clip's title is generated by the SAME `generateContent` service the Creator
 * Studio generators use — cloud (Groq free AI) first when configured, then the
 * opt-in on-device model, then the template engine — with the segment's opening
 * words as the topic and the "hooks" kind (a clip title is a one-line hook for
 * the clip; count 1). The result is honest by construction:
 *
 * - the returned `source` is the routing outcome's source, and the creation UI
 *   shows it with the existing `SourceBadge` next to the title before the clip
 *   is created — a template-engine title is badged "Template engine", never
 *   presented as AI;
 * - when routing produces nothing usable at all, the title falls back to the
 *   plain range title (`clipProjectTitle`) and the source is REPORTED as
 *   "template" with a note — still labelled, never a silent fake "AI title".
 *
 * The generated title is ordinary project data once chosen: it is passed to the
 * clips API as the project's title and stays editable in the studio like any
 * other project title. Generation is an explicit step in the creation flow (one
 * call per clip the user actually pursues), never fired for every proposal on
 * render — the cloud path is a shared, rate-limited free service.
 */
import { generateContent, type GenerationDeps } from "../create/service";
import type { Source } from "../create/model";
import { clipProjectTitle } from "./clipper";

export interface ClipTitleResult {
  /** The title to create the clip project with (always non-empty, ≤ 120 chars). */
  title: string;
  /** Which source actually wrote it — badge this wherever the title is shown at creation time. */
  source: Source;
  /** True when a stronger source was asked for but a weaker one wrote the title. */
  fellBack: boolean;
  /** Plain-language fallback note from the routing, when one applies. */
  note?: string;
}

/** How much of the segment's opening text is offered as the generation topic. */
export const CLIP_TITLE_TOPIC_MAX_CHARS = 280;

const cleanTopic = (text: string): string => text.trim().replace(/\s+/g, " ").slice(0, CLIP_TITLE_TOPIC_MAX_CHARS).trim();

/** A generated line becomes a project title: quotes stripped, whitespace collapsed, capped at the 120-char project limit. */
export function clipTitleFromGenerated(raw: string): string {
  const cleaned = raw.trim().replace(/^["']+|["']+$/g, "").replace(/\s+/g, " ").trim();
  return cleaned.slice(0, 120).trim();
}

/**
 * Generate one clip title through the Phase-3 routing. `deps` is assembled by the
 * caller exactly as the Creator Studio page assembles it (cloud runner only when
 * the site reports its free AI configured; local model only when opted in and
 * ready) — with no runners at all this is the template engine, badged as such.
 */
export async function generateClipTitle(
  input: { sourceTitle: string; segmentText: string; startMs: number; endMs: number },
  deps: GenerationDeps,
): Promise<ClipTitleResult> {
  const topic = cleanTopic(input.segmentText) || cleanTopic(input.sourceTitle) || "Untitled clip";
  const outcome = await generateContent(
    "hooks",
    { topic, style: "curiosity", platform: "shorts", count: 1 },
    deps,
  );
  const generated = outcome.items[0] ? clipTitleFromGenerated(outcome.items[0].title) : "";
  if (!generated) {
    // Routing produced nothing usable: the plain range title, labelled as the
    // template fallback it is (never dressed up as a generated title).
    return {
      title: clipProjectTitle(input.sourceTitle, input.startMs, input.endMs),
      source: "template",
      fellBack: true,
      note: "No title could be generated for this clip, so the plain range title is used instead.",
    };
  }
  return { title: generated, source: outcome.source, fellBack: outcome.fellBack, note: outcome.note };
}
